// Bundles the vendored folk rig (dalabengba-mv, ISC) into one classic script exposing window.PCF. From this directory:
//   node build.mjs . PCF ../../../template/engine/styles/papercraft/folk.js rigs/folk.js
// General form: node build.mjs <root> <global> <out> <entry...>
// Each module becomes a function scope; imports become destructuring from earlier modules' export objects.
import fs from 'node:fs';
import path from 'node:path';
const [root, glob, out, ...entries] = process.argv.slice(2);
const done = new Map(), order = [];
function load(file) {
  if (done.has(file)) return;
  done.set(file, null);
  let src = fs.readFileSync(file, 'utf8');
  const deps = [];
  src = src.replace(/^import\s*\{([^}]*)\}\s*from\s*'([^']+)';?/gm, (_, names, rel) => {
    const dep = path.resolve(path.dirname(file), rel);
    deps.push(dep);
    return `const {${names.replace(/(\w+)\s+as\s+(\w+)/g, '$1: $2')}} = M[${JSON.stringify(path.relative(root, dep).split(path.sep).join('/'))}];`;
  });
  deps.forEach(load);
  const names = [];
  src = src.replace(/^export\s*\{[^}]*\};?/gm, (m) => { names.push(...m.match(/\{([^}]*)\}/)[1].split(',').map((s) => s.trim()).filter(Boolean)); return ''; });
  src = src.replace(/^export\s+(const|function|let|class)\s+(\w+)/gm, (_, k, n) => { names.push(n); return `${k} ${n}`; });
  if (/^\s*(import|export)\b/m.test(src)) throw new Error('unhandled import/export in ' + file);
  const key = JSON.stringify(path.relative(root, file).split(path.sep).join('/'));
  order.push(`M[${key}] = (() => {\n${src}\nreturn { ${names.join(', ')} };\n})();`);
}
entries.forEach((e) => load(path.resolve(root, e)));
const head = `// Generated by esm2iife from ${entries.join(', ')} (dalabengba-mv, ISC: licenses/LICENSE-dalabengba-mv.txt). Do not edit.\n`;
fs.writeFileSync(out, `${head}(() => {\nconst M = {};\n${order.join('\n')}\nwindow.${glob} = Object.assign({}, ...${JSON.stringify(entries.map((e) => path.relative(root, path.resolve(root, e)).split(path.sep).join('/')))}.map((k) => M[k]));\n})();\n`);
console.log('wrote', out, order.length, 'modules');
